1	/**
2	 * Proactive Coherence Guardian
3	 * 
4	 * The component that was architecturally absent: a system that PROACTIVELY
5	 * evaluates surface coverage, detects changes, and triggers enforcement sweeps
6	 * when coherence is at risk.
7	 * 
8	 * This is not reactive. It doesn't wait for content to be submitted.
9	 * It asks: "What haven't I seen? What changed? Is coverage complete?"
10	 */
11	
12	import { eq, and, sql, inArray, ne } from 'drizzle-orm';
13	import { getDb } from '../../db';
14	import { discoveredSurfaces, sweepTriggers, discoveryRuns } from '../../../drizzle/schema';
15	import { generalLog } from '../../_core/logger';
16	import { getRepoRoot } from '../../repo-root';
17	import { notifyOwner } from '../../_core/notification';
18	import { SurfaceInventoryManager, CoverageScorer } from './inventory';
19	import { getAdapter, getAllAdapters } from './adapters';
20	import type {
21	  DiscoveryConfigData,
22	  SweepEvaluation,
23	  SweepResult,
24	  ChangeDetectionResult,
25	  DiscoveredSurfaceData,
26	  AdapterConfig,
27	  SurfaceType,
28	  BusinessTruth,
29	} from './types';
30	import { DiscoveryStatus } from './types';
31	import { remediateSweepResults } from './remediation';
32	import { gatedRemediateSweepResults } from './gravito-gate';
33	import { evaluateCompletenessGate } from './completeness-gate';
34	import { getBusinessTruthContext } from '../../services/truth-context-provider';
35	
36	const log = generalLog.child({ module: 'proactive-coherence-guardian' });
37	
38	// =============================================================================
39	// DISCOVERY ORCHESTRATOR
40	// =============================================================================
41	
42	/**
43	 * Run discovery across all configured adapters for a customer.
44	 * This is the entry point for proactive surface discovery.
45	 */
46	export async function runDiscovery(customerId: string, config: DiscoveryConfigData): Promise<{
47	  runId: string;
48	  totalDiscovered: number;
49	  newSurfaces: number;
50	  staleSurfaces: number;
51	  deadSurfaces: number;
52	  adapterResults: Array<{ adapter: string; surfacesFound: number; durationMs: number; error?: string }>;
53	}> {
54	  const db = await getDb();
55	  if (!db) throw new Error('Database unavailable');
56	
57	  const runId = `discovery_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
58	  const startTime = Date.now();
59	  const inventoryManager = new SurfaceInventoryManager();
60	  const adapterResults: Array<{ adapter: string; surfacesFound: number; durationMs: number; error?: string }> = [];
61	  let allDiscovered: DiscoveredSurfaceData[] = [];
62	
63	  log.info({ customerId, runId, adapters: config.adapters.length }, 'Starting discovery run');
64	
65	  // Record the run
66	  await db.insert(discoveryRuns).values({
67	    runId,
68	    customerId,
69	    adapterType: config.adapters.map(a => a.type).join(','),
70	    status: 'running',
71	    startedAt: new Date(startTime),
72	  });
73	
74	  // Run each enabled adapter
75	  for (const adapterConfig of config.adapters) {
76	    if (!adapterConfig.enabled) continue;
77	
78	    const adapter = getAdapter(adapterConfig.type);
79	    if (!adapter) {
80	      log.error({ adapterType: adapterConfig.type, customerId }, 'COVERAGE GAP: Configured adapter not registered — surfaces of this type will NOT be discovered. Register the adapter or remove from config.');
81	      adapterResults.push({ adapter: adapterConfig.type, surfacesFound: 0, durationMs: 0, error: 'COVERAGE GAP: Adapter not registered' });
82	      // Notify owner about the coverage gap
83	      await notifyOwner({
84	        title: `Surface Discovery: COVERAGE GAP — adapter "${adapterConfig.type}" not registered`,
85	        content: `Customer ${customerId} has adapter "${adapterConfig.type}" configured but it is not registered in the system. Surfaces of this type will NOT be discovered, creating a silent coverage gap. Register the adapter or remove it from the customer config.`,
86	      }).catch(() => {});
87	      continue;
88	    }
89	
90	    const adapterStart = Date.now();
91	    try {
92	      // Validate config first
93	      const validation = await adapter.validateConfig(adapterConfig);
94	      if (!validation.valid) {
95	        log.warn({ adapterType: adapterConfig.type, errors: validation.errors }, 'Invalid adapter config');
96	        adapterResults.push({
97	          adapter: adapterConfig.type,
98	          surfacesFound: 0,
99	          durationMs: Date.now() - adapterStart,
100	          error: `Invalid config: ${validation.errors?.join(', ')}`,
101	        });
102	        continue;
103	      }
104	
105	      // Run discovery
106	      const discovered = await adapter.discover(customerId, adapterConfig);
107	      allDiscovered = allDiscovered.concat(discovered);
108	
109	      adapterResults.push({
110	        adapter: adapterConfig.type,
111	        surfacesFound: discovered.length,
112	        durationMs: Date.now() - adapterStart,
113	      });
114	    } catch (error) {
115	      const errMsg = error instanceof Error ? error.message : String(error);
116	      log.error({ adapterType: adapterConfig.type, error: errMsg }, 'Adapter discovery failed');
117	      adapterResults.push({
118	        adapter: adapterConfig.type,
119	        surfacesFound: 0,
120	        durationMs: Date.now() - adapterStart,
121	        error: errMsg,
122	      });
123	    }
124	  }
125	
126	  // Update inventory with all discovered surfaces
127	  const inventoryResult = await inventoryManager.updateInventory(customerId, allDiscovered);
128	
129	  // Apply exclusion patterns
130	  if (config.exclusionPatterns.length > 0) {
131	    for (const pattern of config.exclusionPatterns) {
132	      try {
133	        const regex = new RegExp(pattern, 'i');
134	        const toIgnore = allDiscovered.filter(s => regex.test(s.url) || (s.title && regex.test(s.title)));
135	        for (const surface of toIgnore) {
136	          await db.update(discoveredSurfaces)
137	            .set({ status: 'ignored' })
138	            .where(
139	              and(
140	                eq(discoveredSurfaces.surfaceId, surface.surfaceId),
141	                eq(discoveredSurfaces.customerId, customerId),
142	              )
143	            );
144	        }
145	      } catch {
146	        log.warn({ pattern }, 'Invalid exclusion pattern');
147	      }
148	    }
149	  }
150	
151	  // Update the run record
152	  const durationMs = Date.now() - startTime;
153	  await db.update(discoveryRuns)
154	    .set({
155	      status: 'completed',
156	      surfacesDiscovered: allDiscovered.length,
157	      surfacesNew: inventoryResult.newSurfaces,
158	      surfacesStale: inventoryResult.staleSurfaces,
159	      surfacesDead: inventoryResult.deadSurfaces,
160	      durationMs,
161	      completedAt: new Date(),
162	    })
163	    .where(eq(discoveryRuns.runId, runId));
164	
165	  log.info({
166	    customerId, runId, durationMs,
167	    totalDiscovered: allDiscovered.length,
168	    new: inventoryResult.newSurfaces,
169	    stale: inventoryResult.staleSurfaces,
170	    dead: inventoryResult.deadSurfaces,
171	  }, 'Discovery run complete');
172	
173	  return {
174	    runId,
175	    totalDiscovered: allDiscovered.length,
176	    newSurfaces: inventoryResult.newSurfaces,
177	    staleSurfaces: inventoryResult.staleSurfaces,
178	    deadSurfaces: inventoryResult.deadSurfaces,
179	    adapterResults,
180	  };
181	}
182	
183	// =============================================================================
184	// CHANGE DETECTOR
185	// =============================================================================
186	
187	/**
188	 * Detect changes across all known surfaces for a customer.
189	 * Verifies each surface against its adapter to find stale/dead content.
190	 */
191	export async function detectChanges(customerId: string): Promise<ChangeDetectionResult> {
192	  const db = await getDb();
193	  if (!db) throw new Error('Database unavailable');
194	
195	  const startTime = Date.now();
196	  const inventoryManager = new SurfaceInventoryManager();
197	  const inventory = await inventoryManager.getInventory(customerId);
198	
199	  const changedSurfaces: ChangeDetectionResult['changedSurfaces'] = [];
200	  const deadSurfaces: ChangeDetectionResult['deadSurfaces'] = [];
201	
202	  // Only check active surfaces (not dead/ignored)
203	  const activeSurfaces = inventory.filter(s => s.status !== 'dead' && s.status !== 'ignored');
204	
205	  for (const entry of activeSurfaces) {
206	    const adapter = getAdapter(entry.discoverySource);
207	    if (!adapter) continue;
208	
209	    try {
210	      const verification = await adapter.verify({
211	        surfaceId: entry.surfaceId,
212	        url: entry.url,
213	        surfaceType: entry.surfaceType as SurfaceType,
214	        contentHash: entry.contentHash,
215	        lastSeen: entry.lastSeen,
216	        metadata: (entry.metadata as unknown as Record<string, unknown>) || {},
217	        discoverySource: entry.discoverySource,
218	      });
219	
220	      if (!verification.exists) {
221	        deadSurfaces.push({
222	          surfaceId: entry.surfaceId,
223	          url: entry.url,
224	          lastSeen: entry.lastSeen,
225	        });
226	        await db.update(discoveredSurfaces)
227	          .set({ status: 'dead' })
228	          .where(eq(discoveredSurfaces.id, entry.id));
229	      } else if (verification.contentHash && verification.contentHash !== entry.contentHash) {
230	        changedSurfaces.push({
231	          surfaceId: entry.surfaceId,
232	          oldHash: entry.contentHash,
233	          newHash: verification.contentHash,
234	        });
235	        await db.update(discoveredSurfaces)
236	          .set({
237	            contentHash: verification.contentHash,
238	            contentSnapshot: verification.contentSnapshot || entry.contentSnapshot,
239	            status: entry.status === 'reviewed' ? 'stale' : entry.status,
240	            lastSeen: new Date(),
241	          })
242	          .where(eq(discoveredSurfaces.id, entry.id));
243	      }
244	    } catch (error) {
245	      log.debug({ surfaceId: entry.surfaceId, error: error instanceof Error ? error.message : String(error) }, 'Verification error');
246	    }
247	  }
248	
249	  return {
250	    changedSurfaces,
251	    newSurfaces: [], // New surfaces are found during discovery, not change detection
252	    deadSurfaces,
253	    totalChecked: activeSurfaces.length,
254	    durationMs: Date.now() - startTime,
255	  };
256	}
257	
258	// =============================================================================
259	// SWEEP EVALUATOR & TRIGGER
260	// =============================================================================
261	
262	/**
263	 * Evaluate whether a coverage sweep should be triggered.
264	 * This is the completeness gate — the thing that asks "have we seen everything?"
265	 */
266	export async function evaluateForSweep(customerId: string, config?: DiscoveryConfigData): Promise<SweepEvaluation> {
267	  const coverageScorer = new CoverageScorer();
268	  const coverage = await coverageScorer.computeCoverage(customerId);
269	
270	  const thresholds = config?.coverageThresholds || {
271	    sweepTrigger: 0.8,
272	    criticalThreshold: 0.5,
273	    staleThresholdDays: 30,
274	  };
275	
276	  const reasons: string[] = [];
277	  let shouldTrigger = false;
278	
279	  // Reason 1: Coverage is below the sweep trigger threshold
280	  if (coverage.overallCoverage < thresholds.sweepTrigger) {
281	    shouldTrigger = true;
282	    reasons.push(`Coverage (${(coverage.overallCoverage * 100).toFixed(1)}%) is below the trigger threshold of ${(thresholds.sweepTrigger * 100).toFixed(1)}%`);
283	  }
284	
285	  // Reason 2: Coverage is critically low
286	  if (coverage.overallCoverage < thresholds.criticalThreshold) {
287	    shouldTrigger = true;
288	    reasons.push(`CRITICAL: Coverage (${(coverage.overallCoverage * 100).toFixed(1)}%) is below the critical threshold of ${(thresholds.criticalThreshold * 100).toFixed(1)}%`);
289	  }
290	
291	  // Reason 3: Stale surfaces exist
292	  if (coverage.staleSurfaces > 0) {
293	    shouldTrigger = true;
294	    reasons.push(`${coverage.staleSurfaces} surfaces are stale (not reviewed recently)`);
295	  }
296	
297	  // Reason 4: New, unreviewed surfaces exist.
298	  // CoverageReportData has no newCount field; the count of surfaces awaiting
299	  // review is derived from the ones it does carry — everything that is not
300	  // reviewed, stale, dead or ignored.
301	  const newSurfaceCount = Math.max(
302	    0,
303	    coverage.totalSurfaces
304	      - coverage.reviewedSurfaces
305	      - coverage.staleSurfaces
306	      - coverage.deadSurfaces
307	      - coverage.ignoredSurfaces,
308	  );
309	  if (newSurfaceCount > 0) {
310	    shouldTrigger = true;
311	    reasons.push(`${newSurfaceCount} new surfaces are awaiting review`);
312	  }
313	
314	  // Determine priority
315	  const priority = coverage.overallCoverage < thresholds.criticalThreshold ? 'critical' : 'medium';
316	
317	  const affectedSurfaces = shouldTrigger ? (await getDb().select().from(discoveredSurfaces).where(and(eq(discoveredSurfaces.customerId, customerId), ne(discoveredSurfaces.status, 'ignored')))).map(s => s.surfaceId) : [];
318	
319	  return {
320	    shouldTrigger,
321	    reasons,
322	    priority,
323	    coverageAtEvaluation: coverage.overallCoverage,
324	    affectedSurfaces,
325	  };
326	}
327	
328	/**
329	 * Trigger a sweep run and store it in the database.
330	 */
331	export async function triggerSweep(customerId: string, evaluation: SweepEvaluation, triggerType: 'manual' | 'scheduled'): Promise<SweepResult> {
332	  const db = await getDb();
333	  if (!db) throw new Error('Database unavailable');
334	
335	  const sweepId = `sweep_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
336	  const startTime = Date.now();
337	
338	  // Store the trigger record
339	  await db.insert(sweepTriggers).values({
340	    sweepId,
341	    customerId,
342	    triggerType,
343	    status: 'triggered',
344	    triggeredAt: new Date(),
345	    evaluation: JSON.stringify(evaluation),
346	    priority: evaluation.priority,
347	  });
348	
349	  log.info({ customerId, sweepId, triggerType, priority: evaluation.priority }, 'Sweep triggered, starting remediation...');
350	
351	  // Get all active surfaces for the customer
352	  const surfacesToSweep = await db.select().from(discoveredSurfaces).where(
353	    and(
354	      eq(discoveredSurfaces.customerId, customerId),
355	      inArray(discoveredSurfaces.status, ['new', 'stale', 'reviewed'])
356	    )
357	  );
358	
359	  if (surfacesToSweep.length === 0) {
360	    log.warn({ customerId, sweepId }, 'Sweep triggered but no active surfaces found to process.');
361	    const result: SweepResult = { sweepId, status: 'completed', surfacesProcessed: 0, durationMs: Date.now() - startTime, errors: [] };
362	    await db.update(sweepTriggers).set({ status: 'completed', result: JSON.stringify(result) }).where(eq(sweepTriggers.sweepId, sweepId));
363	    return result;
364	  }
365	
366	  // Map to Shield-compatible format
367	  const shieldInputs = surfacesToSweep.map(surface => ({
368	    surface_id: surface.surfaceId,
369	    customer_id: customerId,
370	    surface_type: mapSurfaceTypeToShieldType(surface.surfaceType),
371	    content_url: surface.url,
372	    content_snapshot: surface.contentSnapshot || '',
373	  }));
374	
375	  // Get business truth context
376	  const truthContext = await getBusinessTruthContext(customerId) as BusinessTruth;
377	
378	  // Execute remediation via Shield
379	  let shieldResults: Awaited<ReturnType<typeof remediateSweepResults>>;
380	  try {
381	    // Use the gated function to ensure Gravito review
382	    const remediationInput = shieldResults.map(r => ({ ...r, truthContext }));
383	    shieldResults = await gatedRemediateSweepResults(remediationInput);
384	
385	  } catch (error) {
386	    const errMsg = error instanceof Error ? error.message : String(error);
387	    log.error({ customerId, sweepId, error: errMsg }, 'Remediation sweep failed');
388	    const result: SweepResult = { sweepId, status: 'failed', surfacesProcessed: 0, durationMs: Date.now() - startTime, errors: [errMsg] };
389	    await db.update(sweepTriggers).set({ status: 'failed', result: JSON.stringify(result) }).where(eq(sweepTriggers.sweepId, sweepId));
390	    return result;
391	  }
392	
393	  // Post-process results (e.g., update surface status)
394	  const errors: string[] = [];
395	  for (const res of shieldResults) {
396	    if (res.status === 'error') {
397	      errors.push(`Surface ${res.surface_id}: ${res.error}`);
398	      continue;
399	    }
400	    await db.update(discoveredSurfaces)
401	      .set({ status: 'reviewed', lastSeen: new Date() })
402	      .where(and(eq(discoveredSurfaces.surfaceId, res.surface_id), eq(discoveredSurfaces.customerId, customerId)));
403	  }
404	
405	  const result: SweepResult = {
406	    sweepId,
407	    status: errors.length > 0 ? 'completed_with_errors' : 'completed',
408	    surfacesProcessed: shieldInputs.length,
409	    durationMs: Date.now() - startTime,
410	    errors,
411	  };
412	
413	  await db.update(sweepTriggers).set({ status: result.status, result: JSON.stringify(result) }).where(eq(sweepTriggers.sweepId, sweepId));
414	
415	  log.info({ customerId, sweepId, duration: result.durationMs, processed: result.surfacesProcessed, errors: errors.length }, 'Remediation sweep complete');
416	
417	  return result;
418	}
419	
420	
421	// =============================================================================
422	// FULL PIPELINE ORCHESTRATOR
423	// =============================================================================
424	
425	/**
426	 * Run the complete proactive coherence pipeline:
427	 * 1. Discover all surfaces
428	 * 2. Detect changes in known surfaces
429	 * 3. Compute coverage
430	 * 4. Evaluate for sweep
431	 * 5. Trigger sweep if needed
432	 * 
433	 * This is what should run on a cron schedule.
434	 */
435	export async function runProactiveCoherencePipeline(customerId: string, config: DiscoveryConfigData): Promise<{
436	  discovery: Awaited<ReturnType<typeof runDiscovery>>;
437	  changes: ChangeDetectionResult;
438	  evaluation: SweepEvaluation;
439	  sweep?: SweepResult;
440	}> {
441	  log.info({ customerId }, 'Starting proactive coherence pipeline');
442	
443	  // Step 1: Discover
444	  const discovery = await runDiscovery(customerId, config);
445	
446	  // Step 2: Detect changes
447	  const changes = await detectChanges(customerId);
448	
449	  // Step 3: Evaluate coverage
450	  const evaluation = await evaluateForSweep(customerId, config);
451	
452	  // Step 4: Trigger sweep if needed
453	  let sweep: SweepResult | undefined;
454	  if (evaluation.shouldTrigger) {
455	    log.info({
456	      customerId,
457	      priority: evaluation.priority,
458	      reasons: evaluation.reasons,
459	      affectedSurfaces: evaluation.affectedSurfaces,
460	    }, 'Sweep triggered');
461	
462	    sweep = await triggerSweep(customerId, evaluation, 'scheduled');
463	  } else {
464	    log.info({ customerId, coverage: evaluation.coverageAtEvaluation }, 'No sweep needed — coverage acceptable');
465	  }
466	
467	  // Step 5: Evaluate completeness gate
468	  const gateResult = await evaluateCompletenessGate(customerId);
469	  log.info({
470	    customerId,
471	    gateStatus: gateResult.gateStatus,
472	    coverage: gateResult.coverageAtEvaluation,
473	    blockReasons: gateResult.blockReasons,
474	  }, 'Completeness gate evaluated');
475	
476	  if (gateResult.gateStatus === 'blocked') {
477	    log.warn({
478	      customerId,
479	      blockReasons: gateResult.blockReasons,
480	    }, 'COMPLETENESS GATE BLOCKED after pipeline — coherence cannot be confirmed');
481	  }
482	
483	  return { discovery, changes, evaluation, sweep };
484	}
485	
486	// =============================================================================
487	// HELPERS
488	// =============================================================================
489	
490	function mapSurfaceTypeToShieldType(surfaceType: string): string {
491	  const mapping: Record<string, string> = {
492	    web_page: 'website',
493	    api_endpoint: 'generic',
494	    email_template: 'sales',
495	    chat_config: 'support',
496	    code_component: 'website',
497	    documentation: 'generic',
498	    mobile_screen: 'website',
499	    social_post: 'sales',
500	    ad_copy: 'sales',
501	    slide_deck: 'sales',
502	    other: 'generic',
503	  };
504	  return mapping[surfaceType] || 'generic';
505	}
506	
507	/**
508	 * Get the default discovery config for Gravito's own surfaces (dogfooding).
509	 */
510	export function getDefaultDogfoodConfig(customerId: string): DiscoveryConfigData {
511	  return {
512	    customerId,
513	    adapters: [
514	      {
515	        type: 'code_scanner',
516	        enabled: true,
517	        config: {
518	          rootPath: getRepoRoot(),
519	          framework: 'react',
520	        } as unknown as Record<string, unknown>,
521	      },
522	      {
523	        type: 'documentation',
524	        enabled: true,
525	        config: {
526	          rootPath: getRepoRoot(),
527	        } as unknown as Record<string, unknown>,
528	      },
529	    ],
530	    coverageThresholds: {
531	      sweepTrigger: 0.8,
532	      criticalThreshold: 0.5,
533	      staleThresholdDays: 7,
534	    },
535	    exclusionPatterns: [
536	      'node_modules',
537	      '\\.test\\.',
538	      '_core',
539	      'DashboardLayoutSkeleton',
540	    ],
541	  };
542	}
