// PUBLIC API
// ============================================================================

/**
 * Get the LLM-ready business truth context string.
 * Cached for 5 minutes. Returns empty string if YAML not found.
 */
export function getBusinessTruthContext(): string {
  const now = Date.now();
  if (_cachedContext && (now - _lastLoadTime) < CACHE_TTL_MS) {
    return _cachedContext;
  }

  const raw = loadRawYaml();
  if (!raw) {
    _cachedContext = '';
    _lastLoadTime = now;
    return '';
  }

  _cachedRaw = raw;
  _cachedContext = buildContextString(raw);
  _lastLoadTime = now;
  return _cachedContext;
}

/**
 * Get the raw parsed YAML (cached).
 */
export function getBusinessTruthRaw(): any {
  const now = Date.now();
  if (_cachedRaw && (now - _lastLoadTime) < CACHE_TTL_MS) {
    return _cachedRaw;
  }
  getBusinessTruthContext(); // triggers load
  return _cachedRaw;

