export async function triggerSweep(customerId: string, evaluation: SweepEvaluation, triggerType: SweepTriggerType): Promise<SweepResult> {
  const db = await getDb();
  if (!db) throw new Error('Database unavailable');

  const startTime = Date.now();

  // Store the trigger record. sweep_triggers has no sweepId column — its serial
  // primary key IS the sweep id, which is why SweepResult.sweepId is a number
  // and why the remediation pipeline takes a numeric sweepId.
  const [trigger] = await db.insert(sweepTriggers).values({
    customerId,
    triggerType,
    priority: evaluation.priority,
    reasons: evaluation.reasons,
    affectedSurfaces: evaluation.affectedSurfaces,
    coverageAtTrigger: evaluation.coverageAtEvaluation,
    status: 'triggered',
  }).returning({ id: sweepTriggers.id });
  const sweepId = trigger.id;

  log.info({ customerId, sweepId, triggerType, priority: evaluation.priority }, 'Sweep triggered, starting remediation...');

  // Get all active surfaces for the customer. The inventory only ever writes the
  // DiscoveryStatus values, so match against those rather than a literal.
  const surfacesToSweep = await db.select().from(discoveredSurfaces).where(
    and(
      eq(discoveredSurfaces.customerId, customerId),
      inArray(discoveredSurfaces.status, [
        DiscoveryStatus.DISCOVERED,
        DiscoveryStatus.STALE,
        DiscoveryStatus.REVIEWED,
      ])
    )
  );

  if (surfacesToSweep.length === 0) {
    log.warn({ customerId, sweepId }, 'Sweep triggered but no active surfaces found to process.');
    const result: SweepResult = {
      sweepId,
      surfacesReviewed: 0,
      surfacesRemediated: 0,
      issuesFound: 0,
      durationMs: Date.now() - startTime,
    };
    await db.update(sweepTriggers)
      .set({ status: 'completed', surfacesReviewed: 0, surfacesRemediated: 0, durationMs: result.durationMs, completedAt: new Date() })
      .where(eq(sweepTriggers.id, sweepId));
    return result;
  }

  // Map to Shield-compatible format
  const shieldInputs = surfacesToSweep.map(surface => ({
    surface_id: surface.surfaceId,
    customer_id: customerId,
    surface_type: mapSurfaceTypeToShieldType(surface.surfaceType),
    content_url: surface.url,
    content_snapshot: surface.contentSnapshot || '',
    // lastScore is the surface's most recent coherence score, or 0 when it has
    // never been scored — a never-scored surface is the worst case, not the best.
    score: surface.lastScore ?? 0,
  }));

  // The gate takes the surfaces plus their prior review verdict. The guardian
  // runs no review of its own here — it re-submits each surface with its stored
  // score and lets the gate produce the issues and patches.
  const surfaceResults = shieldInputs.map(input => ({
    surfaceId: input.surface_id,
    surfaceUrl: input.content_url,
    content: input.content_snapshot,
    reviewResult: {
      score: input.score,
      issues: [],
      patches: [],
      block_release: false,
    },
  }));

  // Get business truth context — an LLM-ready string, loaded from the truth YAML.
  const truthContext = getBusinessTruthContext();

  // Execute remediation via the gated pipeline (ensures Gravito review)
  let gateResults: Awaited<ReturnType<typeof gatedRemediateSweepResults>>;
  try {
    gateResults = await gatedRemediateSweepResults(sweepId, customerId, surfaceResults, truthContext);
  } catch (error) {
    const errMsg = error instanceof Error ? error.message : String(error);
    log.error({ customerId, sweepId, error: errMsg }, 'Remediation sweep failed');
    const result: SweepResult = {
      sweepId,
      surfacesReviewed: 0,
      surfacesRemediated: 0,
      issuesFound: 0,
      durationMs: Date.now() - startTime,
    };
    await db.update(sweepTriggers)
      .set({ status: 'failed', durationMs: result.durationMs, completedAt: new Date() })
      .where(eq(sweepTriggers.id, sweepId));
    return result;
  }

  // Post-process results — a surface counts as remediated only if the gate
  // accepted its rewrite; anything else stays as it was and is reported.
  const errors: string[] = [];
  let surfacesRemediated = 0;
  for (const res of gateResults.results) {
    if (!res.accepted) {
      errors.push(`Surface ${res.surfaceId}: rejected by the Gravito gate after ${res.attempts} attempt(s)`);
      continue;
    }
    surfacesRemediated++;
    await db.update(discoveredSurfaces)
      .set({ status: DiscoveryStatus.REVIEWED, lastReviewedAt: new Date(), lastSeen: new Date() })
      .where(and(eq(discoveredSurfaces.surfaceId, res.surfaceId), eq(discoveredSurfaces.customerId, customerId)));
  }

  // "Issues found" = every surface the gate did not clear cleanly: blocked,
  // blocked because Gravito was unavailable, or passed but with warnings.
  const issuesFound = gateResults.blocked + gateResults.blockedUnavailable + gateResults.passedWithWarnings;

  const result: SweepResult = {
    sweepId,
    surfacesReviewed: gateResults.totalSurfaces,
    surfacesRemediated,
    issuesFound,
    durationMs: Date.now() - startTime,
  };

  await db.update(sweepTriggers)
    .set({
      status: errors.length > 0 ? 'completed_with_errors' : 'completed',
      surfacesReviewed: result.surfacesReviewed,
      surfacesRemediated: result.surfacesRemediated,
      durationMs: result.durationMs,
      completedAt: new Date(),
    })
    .where(eq(sweepTriggers.id, sweepId));

  log.info({
    customerId, sweepId,
    duration: result.durationMs,
    reviewed: result.surfacesReviewed,
    remediated: result.surfacesRemediated,
    issuesFound: result.issuesFound,
    errors: errors.length,
  }, 'Remediation sweep complete');

  return result;
}

